      { title: 'ĐIỀU KHIỂN CẢM ỨNG & REMOTE TIỆN LỢI, HẸN GIỜ 24H CHỦ ĐỘNG VÀ TIẾT KIỆM', desc: 'Được trang bị bộ đôi điều khiển thông minh gồm bảng cảm ứng hiện đại và remote từ xa, máy cho phép bạn thao tác và tùy chỉnh mọi chế độ một cách dễ dàng. Nhờ sự tiện lợi này, bạn có thể tận hưởng trọn vẹn khoảnh khắc thư giãn trên sofa hay trong chăn ấm mà vẫn dễ dàng thay đổi nhiệt độ hoặc hẹn giờ tắt máy không cần di chuyển.' }
