    highlights: [
      { title: 'CÔNG NGHỆ BOOST MASTER – GIÓ MẠNH VƯỢT TRỘI, TIẾT KIỆM ĐIỆN NĂNG', desc: 'Quạt cây Livotec S-100 được trang bị công nghệ Boost Master hiện đại, tạo lưu lượng gió lên đến 71m³/phút, làm mát nhanh và đều cho không gian rộng 20–30m². So với các dòng quạt phổ thông chỉ đạt khoảng 50–55m³/phút, Livotec S-100 cho cảm giác mát nhanh hơn rõ rệt ngay từ khi vừa bật máy.' },
      { title: 'CÔNG NGHỆ TURBO – FAN', desc: 'Quạt cây Livotec S-100 được tích hợp công nghệ Turbo-Fan, tạo luồng gió mạnh với vận tốc lên đến 7m/s, dễ dàng xua tan cảm giác oi bức trong những ngày nắng nóng cao điểm. So với các dòng quạt truyền thống có tốc độ gió hạn chế, quạt cây Livotec S-100 mang lại luồng gió mát xa vượt trội, giúp căn phòng luôn thông thoáng và dễ chịu.' },
      { title: 'CÔNG NGHỆ FAST ANGLE – LAN TỎA HƠI MÁT ĐỀU KHẮP PHÒNG', desc: 'Quạt cây Livotec S-100 được tối ưu khả năng phân bổ gió nhờ công nghệ Fast Angle với tốc độ đảo chiều lên đến 12 vòng/phút. Kết hợp cùng sải cánh lớn và lưu lượng gió mạnh, luồng gió mát từ quạt được lan tỏa đồng đều khắp không gian, vượt trội so với các dòng quạt thông thường cùng công suất chỉ tập trung làm mát một điểm.' },
      { title: 'CÔNG NGHỆ EXTENSION 120 MÁT RỘNG, MÁT XA', desc: 'Nhờ góc xoay lên tới 120 độ, công nghệ Extension 120 giúp quạt cây Livotec S-100 phân bổ luồng gió mát đều khắp không gian phòng. Dù bạn đang làm việc, thư giãn hay sinh hoạt cùng gia đình, không khí luôn mát dễ chịu, hạn chế tình trạng chỉ mát cục bộ như ở các dòng quạt thông thường' },
      { title: 'TIẾT KIỆM 20% ĐIỆN NĂNG', desc: 'Nhờ tối ưu hiệu suất động cơ, quạt cây Livotec giúp tiết kiệm điện năng đáng kể trong quá trình sử dụng. Đạt chuẩn nhãn năng lượng 5 sao, Livotec S-100 mang đến giải pháp làm mát kinh tế, phù hợp với nhu cầu sinh hoạt hằng ngày của gia đình hiện đại.' },
      { title: '3 CẤP ĐỘ GIÓ TÙY CHỈNH', desc: 'Quạt Livotec S-100 cho phép bạn điều chỉnh dễ dàng 3 mức gió phù hợp với từng nhu cầu sử dụng.' },
      { title: 'VỆ SINH DỄ DÀNG – GIÓ MÁT TRONG LÀNH', desc: 'Quạt cây Livotec S-100 được thiết kế đầu quạt có thể tháo rời, giúp bạn lau chùi và vệ sinh nhanh gọn chỉ trong vài phút. Luồng gió vì thế luôn sạch sẽ, trong lành, để cả nhà yên tâm tận hưởng gió mát dễ chịu mỗi ngày' },
      { title: 'BẢO HÀNH CHÍNH HÃNG ĐẾN 24 THÁNG', desc: 'Quạt cây S-100 được bảo hành chính hãng 24 tháng cùng dịch vụ chăm sóc khách hàng chuyên nghiệp từ Livotec. Nhờ đó, bạn và gia đình có thể yên tâm tận hưởng làn gió mát dễ chịu mỗi ngày mà không phải lo lắng về các vấn đề phát sinh trong quá trình vận hành.' }
    ],
