      { title: 'CÔNG NGHỆ ACF – TỰ ĐỘNG LÀM SẠCH 4 BƯỚC', desc: 'Tạo nước ngưng tụ bụi bẩn Đóng băng dàn lạnh Rã đông và rửa sạch cặn bám Sấy khô dàn lạnh Bạn cũng không cần vệ sinh dàn lạnh quá thường xuyên như trước, vừa tiết kiệm thời gian bảo dưỡng vừa giúp máy vận hành bền bỉ hơn theo thời gian.' },
      { title: 'CÔNG NGHỆ I-CHILL – DỄ DÀNG THEO DÕI TÌNH TRẠNG MÁY', desc: 'Công nghệ i-Chill giúp hiển thị mã lỗi trực tiếp trên màn hình, hỗ trợ bạn nhanh chóng kiểm tra tình trạng hoạt động của máy khi có sự cố xảy ra. Nhờ đó, việc kiểm tra, bảo trì hay sửa chữa cũng trở nên thuận tiện và tiết kiệm thời gian hơn.' },
      { title: 'CÔNG NGHỆ AMCAAI BẢO VỆ GIÀN NÓNG', desc: 'Công nghệ AMCAAI trên điều hòa Livotec DHV10.8J Inverter, giúp tăng khả năng bảo vệ dàn nóng trước các điều kiện thời tiết ngoài trời khắc nghiệt.' },
      { title: 'I-TIME – HẸN GIỜ LINH HOẠT, DỄ SỬ DỤNG', desc: 'Bạn có thể cài đặt thời gian bật/tắt theo nhu cầu trong ngày. Điều hòa sẽ tự vận hành đúng thời điểm, giúp tiết kiệm điện và tiện lợi hơn, không còn lo quên tắt máy.' }
